/* Generated by scripts/build.mjs from assets/schedule-feed.js — do not edit.
   Same statements, same order, same values; only the comments and the blank lines are
   gone. Edit assets/schedule-feed.js and rebuild. */
(function () {
  const box = document.getElementById("calfeed-content");
  const status = document.getElementById("calfeed-status");
  if (!box || !status) return;

  let token = "";
  const text = (key) => typeof t === "function" ? t(key) : key;
  const esc = (value) => String(value).replace(/&/g, "&amp;").replace(/</g, "&lt;")
    .replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  const signedIn = () => typeof lmSignedIn !== "function" || lmSignedIn();
  const urls = () => {
    const httpsUrl = `https://europe-central2-materio-502513.cloudfunctions.net/calendarFeed?t=${encodeURIComponent(token)}`;
    return { httpsUrl, webcalUrl: httpsUrl.replace(/^https:/, "webcal:") };
  };

  function render() {
    document.getElementById("calfeed-title").textContent = text("calfeed_title");
    document.getElementById("calfeed-lead").textContent = text("calfeed_lead");
    status.textContent = "";
    if (!signedIn()) {
      box.innerHTML = `<p class="muted">${esc(text("calfeed_signin"))}</p>`;
      return;
    }
    if (!token) {
      box.innerHTML = `<p class="mat-tools"><button type="button" class="btn btn-ghost btn-sm" id="calfeed-connect"${window.lmAccount ? "" : " disabled"}>${esc(text("calfeed_connect"))}</button></p>`;
      return;
    }
    const { httpsUrl, webcalUrl } = urls();

    box.innerHTML = `<p class="mat-tools">
      <a class="btn btn-ghost btn-sm" target="_blank" rel="noopener" href="https://calendar.google.com/calendar/r?cid=${encodeURIComponent(webcalUrl)}">${esc(text("calfeed_google"))}</a>
      <a class="btn btn-ghost btn-sm" href="${esc(webcalUrl)}">${esc(text("calfeed_apple"))}</a>
      <a class="btn btn-ghost btn-sm" target="_blank" rel="noopener" href="https://outlook.live.com/calendar/0/addfromweb?url=${encodeURIComponent(httpsUrl)}&amp;name=LiczMat">${esc(text("calfeed_outlook"))}</a>
    </p>
    <p class="field-note">${esc(text("calfeed_google_hint"))}</p>
    <p class="field-note">${esc(text("calfeed_refresh_hint"))}</p>
    <p class="mat-tools">
      <button type="button" class="btn btn-ghost btn-sm" id="calfeed-copy">${esc(text("calfeed_copy"))}</button>
      <button type="button" class="btn btn-ghost btn-sm" id="calfeed-rotate">${esc(text("calfeed_rotate"))}</button>
    </p>
    <p class="field-note">${esc(text("calfeed_private_hint"))}</p>`;
  }

  async function load(action) {
    status.textContent = "";
    try {
      token = await window.lmAccount.calendarFeed(action);
      render();
    } catch (error) {
      const code = String(error && error.code || "");
      status.textContent = code.includes("permission-denied")
        ? text("calfeed_pro_error") : text("calfeed_error");
    }
  }

  box.addEventListener("click", async (event) => {
    if (event.target.closest("#calfeed-connect")) await load("get");
    if (event.target.closest("#calfeed-copy")) {
      const { httpsUrl } = urls();
      try {
        await navigator.clipboard.writeText(httpsUrl);
        status.textContent = text("calfeed_copied");
      } catch (error) {
        box.insertAdjacentHTML("beforeend", `<p><input id="calfeed-fallback" readonly value="${esc(httpsUrl)}" aria-label="${esc(text("calfeed_copy"))}"></p>`);
        const input = document.getElementById("calfeed-fallback");
        input.select();
      }
    }
    if (event.target.closest("#calfeed-rotate") && window.confirm(text("calfeed_rotate_confirm"))) await load("rotate");
  });

  document.addEventListener("lm-account-ready", render);
  document.addEventListener("langchange", render);
  render();
}());
